"use client";

import { useState, useLayoutEffect, useRef } from "react";
import Image from "next/image";
import NextLink from "next/link";
import { editorialItem, EditorialReveal, LongArrow, AboutDetails, CaseStudyPage, ContactPage, ServicesPage, WorkPage } from "./content";
import { defaultImages } from "./data";
export type WebsitePage = "home" | "services" | "work" | "about" | "contact" | "case-study";
import { motion, useReducedMotion, useScroll, useTransform } from "framer-motion";
import styles from "./resume.module.css";
import "./fonts.css";

const defaultPortrait = "https://images.pexels.com/photos/30712814/pexels-photo-30712814.jpeg?auto=compress&cs=tinysrgb&w=1600";

function rememberContactReturn(path: string) {
  try { sessionStorage.setItem("alexandria-contact-return", path); } catch { /* Navigation still works when storage is unavailable. */ }
}

function BrandLogo() {
  return (<svg className={styles.brandLogo} aria-hidden="true" width="307" height="280" viewBox="0 0 307 280" fill="none" xmlns="http://www.w3.org/2000/svg">
<path d="M225.174 78.5332C235.763 57.0285 273.543 27.6714 306.448 78.999C294.763 76.9668 269.3 90.9224 276.948 147.498C286.509 218.218 292.948 279.999 228.371 279.999C191.819 279.999 142.859 255.207 127.456 247.078C115.771 241.388 86.0273 228.149 63.1885 229.397C27.7325 231.335 2.75896 248.21 0 252.418C6.5192 242.219 43.0872 219.87 73.2803 219.87C134.75 219.87 157.398 243.919 201.448 247.078C243.948 250.126 259.448 203.96 259.448 133.499C259.448 81.0702 277.398 77.9084 283.948 70.999C279.168 63.6832 264.448 52.4987 251.21 58.084C238.132 63.602 226.946 75.5649 225.174 78.5332C225.097 78.6886 225.022 78.8436 224.948 78.998C224.981 78.885 225.057 78.7286 225.174 78.5332ZM31.4482 124.76C34.8098 127.92 49.513 132.345 65.6484 134.74C81.784 137.136 109.349 136.736 114.318 134.74C99.4105 154.203 74.71 155.035 63.4561 154.203C64.4791 156.366 66.3473 160.212 77.9258 166.18C101.164 178.157 110.226 179.488 118.703 180.652C113.003 182.815 81.6085 187.34 61.2637 172.169C40.9188 156.998 33.056 136.404 31.4482 124.76ZM44.1621 0C58.9238 17.4664 98.006 54.8942 136.24 64.875C174.474 74.8558 196.31 94.3191 202.448 102.803C172.631 91.8239 175.704 94.3186 124.403 85.835C83.3629 79.048 66.9642 54.8941 56.4395 38.9248C55.7087 41.5863 52.5823 40.0231 63.4561 72.3604C74.33 104.698 102.772 127.089 115.634 134.242C104.525 131.747 77.135 119.071 56.4395 88.3301C35.7439 57.5893 39.6313 16.6347 44.1621 0Z" fill="#E1B77B"/>
</svg>);
}

type CycleSection = "work" | "about" | "services";
const sectionOrder: CycleSection[] = ["work", "about", "services"];
const sectionLabels = { work: "Work", about: "About", services: "Services" };

function CycleNavigation({ section, onNavigate }: { section: CycleSection; onNavigate?: (direction: number) => void }) {
  const index = sectionOrder.indexOf(section);
  const previous = sectionOrder[(index + 2) % 3];
  const next = sectionOrder[(index + 1) % 3];
  return <nav className={styles.spreadNavigation} aria-label="Explore portfolio">
    {onNavigate ? <>
      <button onClick={() => onNavigate(-1)} className={styles.workDirection} aria-label={`Previous section: ${sectionLabels[previous]}`}><LongArrow left /><span>{sectionLabels[previous]}</span></button>
      <button onClick={() => onNavigate(1)} className={styles.servicesDirection} aria-label={`Next section: ${sectionLabels[next]}`}><span>{sectionLabels[next]}</span><LongArrow /></button>
    </> : <>
      <NextLink href={`/${previous}`} className={styles.workDirection}><LongArrow left /><span>{sectionLabels[previous]}</span></NextLink>
      <NextLink href={`/${next}`} className={styles.servicesDirection}><span>{sectionLabels[next]}</span><LongArrow /></NextLink>
    </>}
  </nav>;
}

function EditorialHome({ portraitUrl, imageUrls, initialSection = "about" }: { portraitUrl: string; imageUrls: string[]; initialSection?: CycleSection }) {
  // Matching end panels allow either direction to wrap without crossing another section.
  const panels: CycleSection[] = ["services", "work", "about", "services", "work"];
  const initialIndex = sectionOrder.indexOf(initialSection) + 1;
  const rail = useRef<HTMLDivElement>(null);
  const aboutPanel = useRef<HTMLElement>(null);
  const aboutHero = useRef<HTMLDivElement>(null);
  const aboutDetails = useRef<HTMLElement>(null);
  const { scrollYProgress: aboutProgress } = useScroll({ container: aboutPanel, target: aboutHero, offset: ["start start", "end start"] });
  const portraitOffset = useTransform(aboutProgress, [0, 1], [0, 48]);
  const copyOffset = useTransform(aboutProgress, [0, 1], [0, -36]);
  const reduceMotion = useReducedMotion();
  const [active, setActive] = useState(initialIndex);
  const activeIndex = useRef(initialIndex);
  const moving = useRef(false);
  const settleTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  function settle() {
    const target = rail.current;
    if (!target) return;
    let index = Math.round(target.scrollLeft / target.clientWidth);
    if (index === 0) index = 3;
    else if (index === 4) index = 1;
    target.scrollTo({ left: target.clientWidth * index, behavior: "instant" });
    activeIndex.current = index;
    setActive(index);
    moving.current = false;
    if (settleTimer.current) clearTimeout(settleTimer.current);
  }

  useLayoutEffect(() => {
    const target = rail.current;
    if (!target) return;
    activeIndex.current = initialIndex;
    setActive(initialIndex);
    target.scrollTo({ left: target.clientWidth * initialIndex, behavior: "instant" });
    const observer = new ResizeObserver(() => {
      target.scrollTo({ left: activeIndex.current * target.clientWidth, behavior: "instant" });
    });
    observer.observe(target);
    return () => {
      observer.disconnect();
      if (settleTimer.current) clearTimeout(settleTimer.current);
    };
  }, [initialIndex]);

  function exploreAbout() {
    const panel = aboutPanel.current;
    const details = aboutDetails.current;
    if (!panel || !details) return;
    const top = details.getBoundingClientRect().top - panel.getBoundingClientRect().top + panel.scrollTop;
    details.focus({ preventScroll: true });
    panel.scrollTo({ top, behavior: reduceMotion ? "instant" : "smooth" });
  }

  function navigate(direction: number) {
    const target = rail.current;
    if (!target || moving.current) return;
    moving.current = true;
    target.scrollTo({ left: target.clientWidth * (activeIndex.current + direction), behavior: reduceMotion ? "instant" : "smooth" });
    settleTimer.current = setTimeout(settle, reduceMotion ? 0 : 900);
  }

  return <div className={`${styles.site} ${styles.editorialSite}`}>
    <a className={styles.skipLink} href="#main-content">Skip to content</a>
    <NextLink href="/contact" className={styles.contactTab} onClick={() => rememberContactReturn(`/${panels[active]}`)}><span>Contact me</span><LongArrow /></NextLink>
    <main id="main-content" ref={rail} className={styles.spreadRail} aria-label="Portfolio sections" onScroll={event => {
      const target = event.currentTarget;
      const index = Math.round(target.scrollLeft / target.clientWidth);
      activeIndex.current = index;
      setActive(index);
      if (settleTimer.current) clearTimeout(settleTimer.current);
      settleTimer.current = setTimeout(settle, 180);
    }}>
      {panels.map((section, index) => <section key={index} ref={section === "about" ? aboutPanel : undefined} tabIndex={-1} aria-label={sectionLabels[section]} inert={active !== index} className={`${styles.spreadPanel} ${section === "about" ? styles.aboutPanel : `${styles.destinationPanel} ${section === "services" ? styles.servicesPanel : ""}`}`}>
        {section === "about" ? <>
          <div ref={aboutHero} className={styles.editorialHome}>
          <header className={styles.editorialHeader}><NextLink href="/" className={styles.editorialLogo} aria-label="Alexandria home"><BrandLogo /></NextLink></header>
          <motion.div className={styles.editorialCopy} style={{ y: reduceMotion ? 0 : copyOffset }}>
            <EditorialReveal>
            <motion.h1 variants={reduceMotion ? undefined : editorialItem}>Alexandria<br /><em>Klaus</em></motion.h1>
            <motion.p variants={reduceMotion ? undefined : editorialItem} className={styles.editorialRole}>Senior Architect</motion.p>
            <motion.div variants={reduceMotion ? undefined : editorialItem} className={styles.editorialBio}><div><p>I shape thoughtful spaces through an understanding of context, proportion, and the way people live.</p><p>From the first sketch to the final detail, I bring a clear architectural vision to places made for everyday life.</p></div></motion.div>
            <motion.button variants={reduceMotion ? undefined : editorialItem} type="button" className={`${styles.aboutScrollArrow} ${styles.aboutArrowMobile}`} onClick={exploreAbout} aria-label="Explore skills and experience" aria-controls="about-details">
              <LongArrow down />
            </motion.button>
            </EditorialReveal>
          </motion.div>
          <button type="button" className={`${styles.aboutScrollArrow} ${styles.aboutArrowDesktop}`} onClick={exploreAbout} aria-label="Explore skills and experience" aria-controls="about-details"><LongArrow down /></button>
          <figure className={styles.editorialPortrait}><div className={styles.portraitFrame}><motion.div className={styles.portraitParallax} style={{ y: reduceMotion ? 0 : portraitOffset }}><motion.div className={styles.portraitImageEntrance} initial={reduceMotion ? false : { opacity: 0, scale: 1.04 }} whileInView={{ opacity: 1, scale: 1 }} viewport={{ once: true, amount: .1 }} transition={{ duration: reduceMotion ? 0 : 1.3, ease: [.22, 1, .36, 1] }}><Image src={portraitUrl} alt="Black-and-white portrait of a woman against a dark background" fill priority unoptimized sizes="(max-width: 700px) 100vw, 50vw" /></motion.div></motion.div></div></figure>
          </div>
          <section id="about-details" ref={aboutDetails} tabIndex={-1} className={styles.aboutDetails} aria-label="Skills and experience"><AboutDetails /></section>
        </> : <>
          <div className={styles.panelTop}><button onClick={() => navigate(section === "work" ? 1 : -1)} aria-label="Alexandria home"><BrandLogo /></button></div>
          {section === "work" ? <WorkPage imageUrls={imageUrls} /> : <ServicesPage imageUrls={imageUrls} />}
        </>}
      </section>)}
    </main>
    <div className={styles.sectionAnnouncement} role="status" aria-live="polite">{sectionLabels[panels[active]]}</div>
    <CycleNavigation section={panels[active]} onNavigate={navigate} />
  </div>;
}

export default function AlexandriaResume({ portraitUrl = defaultPortrait, imageUrls = defaultImages, page = "home", projectSlug }: { portraitUrl?: string; imageUrls?: string[]; registryHref?: string; page?: WebsitePage; projectSlug?: string }) {
  if (page === "home" || page === "about" || page === "work" || page === "services") return <EditorialHome portraitUrl={portraitUrl} imageUrls={imageUrls} initialSection={page === "home" ? "about" : page} />;

  return <div id="top" className={`${styles.site} ${page === "contact" ? styles.contactSite : styles.projectSite}`}>
    <a className={styles.skipLink} href="#main-content">Skip to content</a>
    <main id="main-content">
      {page === "contact" ? <ContactPage /> : projectSlug ? <CaseStudyPage slug={projectSlug} imageUrls={imageUrls} /> : null}
    </main>
  </div>;
}

"use client";

import { Box, Button, Divider, Link, Stack, Typography } from "@mui/joy";
import { TbMail } from "react-icons/tb";
import NextLink from "next/link";
import styles from "./resume.module.css";
import { EditorialReveal, LongArrow } from "./content";

export default function Footer({ registryHref = "https://github.com/mesbahismail/Alexandria", compact = false }: { registryHref?: string; compact?: boolean }) {
  return <Box component="footer" id="contact" className={styles.footer} sx={{ pt: compact ? 0 : 6, pb: 3 }}>
    <EditorialReveal>
    {!compact && <>
    <Divider sx={{ bgcolor: "#333333", mb: 5 }} />
    <Stack direction={{ xs: "column", sm: "row" }} justifyContent="space-between" alignItems={{ xs: "flex-start", sm: "center" }} gap={3} sx={{ pb: 5 }}>
      <Stack gap={1.5}>
        <Typography level="h3" fontWeight={400} sx={{ color: "#ffffff" }}>Let’s work <span className={styles.headlineAccent}>together.</span></Typography>
        <Box sx={{ width: "48px", height: "4px", bgcolor: "#E1B77B" }} />
        <Typography sx={{ color: "#aaa", maxWidth: 480 }}>Have a site, a brief, or a space in mind? Let’s start a conversation.</Typography>
      </Stack>
      <Button component={NextLink} href="/contact" startDecorator={<TbMail size={20} />} sx={{ backgroundColor: "transparent", border: "2px solid #E1B77B", color: "#fff", borderRadius: 0, minHeight: 48, px: 2, "&:hover": { bgcolor: "#E1B77B", color: "#111" } }}>GET IN TOUCH</Button>
    </Stack>
    </>}
    <Divider sx={{ bgcolor: "#333333" }} />
    <Stack direction={{ xs: "column", md: "row" }} justifyContent="space-between" alignItems={{ xs: "flex-start", md: "center" }} gap={2} sx={{ py: 3 }}>
      <Typography level="title-lg" sx={{ color: "#fff" }}>ALEXANDRIA</Typography>
      <Typography level="body-sm" sx={{ color: "#aaa" }}>© {new Date().getFullYear()} Alexandria Klaus. All rights reserved.</Typography>
      <Stack direction="row" gap={3}>
        <Link href={registryHref} underline="none" sx={{ color: "#aaa", fontSize: 13, "&:hover": { color: "#E1B77B" } }}>Component registry</Link>
        <Link href="#top" underline="none" endDecorator={<LongArrow compact direction="up" />} sx={{ color: "#aaa", fontSize: 13, "&:hover": { color: "#E1B77B" } }}>Back to top</Link>
      </Stack>
    </Stack>
    <Typography level="body-xs" sx={{ color: "#888" }}>Designed with care by Ismail Mesbah · Photography via Unsplash</Typography>
    </EditorialReveal>
  </Box>;
}

.site { overflow: clip; --contact-tab-height: 108px; --contact-tab-width: 20vw; }
.site :global(a:focus-visible), .site :global(button:focus-visible) { outline: 2px solid #E1B77B; outline-offset: 4px; }
@media (max-width: 1200px) {
  .socials { display: none !important; }
  .hero { gap: 32px !important; }
  .heroCopy { flex: 1; min-width: 0; }
  .portrait { width: 470px !important; height: 500px !important; flex-shrink: 0; }
  .portrait > div { width: 420px !important; height: 420px !important; }
}
@media (max-width: 900px) {
  .header { flex-wrap: wrap; height: auto !important; min-height: 86px; padding-top: 12px; padding-bottom: 12px; }
  .navigation { order: 3; width: 100%; justify-content: space-between; padding: 12px 0 0 !important; margin-left: 0 !important; gap: 12px !important; }
  .navigation > a { margin-left: 0 !important; font-size: 11px; }
  .hero { flex-direction: column !important; padding-right: 0 !important; padding-top: 30px !important; }
  .hero > * { margin-left: 0 !important; }
  .heroCopy { width: 100% !important; }
  .portrait { width: min(560px, 100%) !important; height: auto !important; aspect-ratio: 1; margin-top: 24px !important; }
  .portrait > div { width: calc(100% - 50px) !important; height: calc(100% - 50px) !important; }
}
@media (max-width: 600px) {
  .site :global(#experience > .MuiStack-root:nth-of-type(2)) { flex-direction: column; gap: 28px; }
  .site :global(#experience > .MuiStack-root:nth-of-type(2) > *) { margin-left: 0; }
  .site :global(#experience .MuiDivider-vertical) { display: none; }
}
@media print {
  .header, .site :global(button), .site :global(#contact a), .site :global(#contact) { display: none !important; }
  .site { overflow: visible; print-color-adjust: exact; }
  .hero { gap: 20px !important; }
  .heroCopy { width: 55% !important; }
  .portrait { width: 300px !important; height: 300px !important; }
  .portrait > div { width: 250px !important; height: 250px !important; transform: none !important; }
}

/* A restrained contemporary finish over Alexandria’s original geometry. */
.site {
  --accent: #e1b77b;
  background-image: radial-gradient(ellipse at 80% 8%, rgba(225, 183, 123, .035), transparent 38%);
}
.header {
  border-bottom: 1px solid rgba(225, 183, 123, .12);
  min-height: 88px;
}
.navigation > a {
  position: relative;
  font-size: 11px;
  letter-spacing: .11em;
  color: #a5a5a6;
  transition: color .25s ease;
}
.navigation > a::after {
  content: '';
  position: absolute;
  left: 0;
  right: 0;
  bottom: -9px;
  height: 1px;
  background: var(--accent);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform .25s ease;
}
.navigation > a:hover::after, .navigation > a:focus-visible::after { transform: scaleX(1); }
.site :global(.MuiButton-root) {
  border-width: 1px;
  border-color: rgba(225, 183, 123, .8);
  border-radius: 2px;
  letter-spacing: .075em;
  font-size: 11px;
  min-height: 48px;
  padding-inline: 22px;
  transition: background-color .25s ease, color .25s ease, box-shadow .25s ease, transform .25s ease;
}
.site :global(.MuiButton-root:hover) {
  border-width: 1px;
  border-color: var(--accent);
  background: var(--accent);
  color: #09090a;
  transform: translateY(-2px);
  box-shadow: 0 8px 24px rgba(225, 183, 123, .10);
}
.socials :global(.MuiIconButton-root) { color: #a4a4a5; transition: color .25s, background-color .25s; }
.socials :global(.MuiIconButton-root:hover) { color: var(--accent); background: rgba(225, 183, 123, .06); }
.hero { padding-top: 44px !important; padding-bottom: 16px; }
.heroCopy .heroName {
  font-size: clamp(36px, 3.5vw, 51px);
  font-weight: 400;
  letter-spacing: -.035em;
  line-height: 1.13;
  text-wrap: balance;
}
.heroCopy .heroIntro { color: #c0bfc0; line-height: 1.9; max-width: 540px; }
.heroCopy > :first-child > :last-child { font-size: 19px; letter-spacing: .025em; margin-top: 10px; color: #b6b1a9; }
.portrait > div:nth-child(2) { box-shadow: 0 24px 65px rgba(0, 0, 0, .24); }
.portrait > div:first-child { border-width: 1px !important; border-color: rgba(225, 183, 123, .85) !important; }
.sectionHeading { padding-top: 24px !important; padding-bottom: 35px !important; }
.sectionHeading > :first-child { font-size: clamp(28px, 2.6vw, 36px); letter-spacing: .055em; line-height: 1.3; }
.sectionHeading > :nth-child(2) { font-size: 14px; color: #a8a6a4; font-weight: 400; letter-spacing: .015em; }
.sectionHeading > :last-child { height: 2px; background: #e1b77b; }
.site .projectCard {
  height: 100%;
  border-radius: 3px;
  overflow: hidden;
  background: #111112;
  box-shadow: 0 8px 28px rgba(0, 0, 0, .10);
  transition: transform .35s ease, box-shadow .35s ease;
}
.site .cardImage { isolation: isolate; }
.cardImage::after {
  content: '';
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: linear-gradient(180deg, transparent 65%, rgba(21, 21, 22, .18));
}
.cardImage img { transition: transform .65s cubic-bezier(.2, .6, .2, 1), filter .5s ease; filter: saturate(.82); }
.site .cardBody {
  flex: 1;
  border-width: 1px;
  border-color: #363436;
  border-top: 0;
  background: linear-gradient(125deg, rgba(255,255,255,.018), transparent);
  padding: 28px;
  transition: border-color .3s ease;
}
.cardBody :global(.MuiCardContent-root) { gap: 12px; }
.cardBody :global(.MuiTypography-titleLg) { font-size: 20px; font-weight: 500; letter-spacing: -.015em; }
.cardBody :global(.MuiTypography-bodyMd) { font-size: 14px; line-height: 1.85; }
.cardBody :global(.MuiTypography-h4) { font-weight: 400; letter-spacing: -.02em; }
.cardBody :global(.MuiIconButton-root) { border-width: 1px; border-color: #e1b77b33; color: var(--accent); transition: transform .3s, border-color .3s, background-color .3s; }
.cardBody :global(.MuiIconButton-root:hover) { background: rgba(225,183,123,.06); border-color: var(--accent); transform: rotate(90deg); }
.site .footer { margin-top: 28px; background: radial-gradient(ellipse at 15% 45%, rgba(225,183,123,.035), transparent 65%); }
.footer :global(h3) { font-size: clamp(25px, 2.7vw, 36px); letter-spacing: .035em; }
.footer :global(a) { transition: color .25s ease; }
@media (hover: hover) and (prefers-reduced-motion: no-preference) {
  .projectCard:hover { transform: translateY(-5px); box-shadow: 0 20px 45px rgba(0,0,0,.22); }
  .projectCard:hover .cardImage img { transform: scale(1.035); filter: saturate(1); }
  .projectCard:hover .cardBody { border-color: rgba(225,183,123,.45); }
}
@media (max-width: 600px) {
  .heroCopy .heroName { font-size: clamp(31px, 8.5vw, 43px); }
  .hero { padding-top: 34px !important; }
  .heroCopy .heroIntro { font-size: 15px; }
  .site .cardBody { padding: 23px; }
  .sectionHeading { padding-bottom: 28px !important; }
}
@media (prefers-reduced-motion: reduce) {
  .site *, .site *::before, .site *::after { transition: none !important; }
  .site :global(.MuiButton-root:hover) { transform: none; }
}
@media print {
  .site, .site .projectCard, .site .cardBody, .site .footer { background-image: none; box-shadow: none; }
}

/* Website pages use the same charcoal, gold, and rectangular geometry. */
.skipLink { position: fixed; left: 16px; top: -80px; z-index: 2000; padding: 12px 20px; background: #e1b77b; color: #09090a; }
.skipLink:focus { top: 12px; }
.navigation > a[aria-current="page"] { color: #e1b77b; }
.navigation > a[aria-current="page"]::after { transform: scaleX(1); }
.homePage .hero { min-height: calc(100svh - 240px); }
.innerPage { padding: 58px 16px 60px; color: #f4f2ed; }
.innerPage h1, .innerPage h2, .innerPage h3, .innerPage p { margin: 0; }
.innerPage h2 { font-size: clamp(26px, 2.5vw, 36px); line-height: 1.3; font-weight: 400; letter-spacing: -.025em; }
.innerPage p { color: #aaa8a6; font-size: 15px; line-height: 1.9; }
.eyebrow { color: #e1b77b; font-size: 10px; font-weight: 500; letter-spacing: .16em; text-transform: uppercase; }
.pageHeading { padding: 16px 0 50px; max-width: 800px; }
.pageHeading h1 { margin-top: 20px; font-size: clamp(34px, 3.6vw, 50px); font-weight: 400; line-height: 1.16; letter-spacing: .025em; }
.pageHeading p { margin-top: 20px; max-width: 580px; }
.goldRule { display: block; margin-top: 28px; width: 48px; height: 2px; background: #e1b77b; }
.serviceRows { border-top: 1px solid #343234; }
.serviceRow { display: grid; grid-template-columns: 1fr 1fr; gap: 65px; padding: 44px 0; border-bottom: 1px solid #343234; align-items: center; }
.servicePhoto { position: relative; height: 365px; overflow: hidden; border-radius: 2px; }
.servicePhoto img, .workPhoto img, .aboutPortrait img, .caseHero img { object-fit: cover; filter: grayscale(1) contrast(1.06); }
.serviceCopy { padding: 16px 25px 16px 0; }
.serviceCopy h2 { margin-top: 19px; }
.serviceCopy p { margin-top: 19px; max-width: 475px; }
.serviceCopy ul, .caseDeliverables ul { display: grid; grid-template-columns: 1fr 1fr; gap: 15px 20px; padding: 0; margin: 25px 0 30px; list-style: none; }
.serviceCopy li, .caseDeliverables li { display: flex; gap: 10px; align-items: center; color: #c9c5bf; font-size: 12px; line-height: 1.5; }
.serviceCopy li svg, .caseDeliverables li svg { color: #e1b77b; flex-shrink: 0; }
.inlineLink { display: inline-flex; gap: 12px; align-items: center; color: #e1b77b; font-size: 12px; text-decoration: none; transition: color .25s; }
.inlineLink:hover { color: #e1b77b; }
.inlineLink svg { font-size: 18px; }
