  padding-bottom: 10px;
  text-wrap: initial;
}
.heroCopy .heroName .headlineAccent { display: inline-block; padding-right: .1em; }
.heroCopy > :first-child > :last-child { margin-top: 23px; font-size: 14px; letter-spacing: .13em; text-transform: uppercase; }
.innerPage h1, .innerPage h2, .innerPage h3, .footer :global(h3) {
