.serviceCopy h2 { font-size: clamp(43px, 4vw, 58px); line-height: 1.04; }
.workCaption h2 { margin-top: 10px; font-size: clamp(28px, 2.8vw, 38px); line-height: 1.12; color: #fff; text-shadow: 0 1px 12px #0005; }
