/* A two-page editorial spread, with work to the left and services to the right. */
.editorialSite { background: #09090a; color: #f1e9dc; }
.spreadRail { display: flex; width: 100%; height: 100svh; overflow-x: auto; overflow-y: hidden; scroll-snap-type: x mandatory; scrollbar-width: none; overscroll-behavior-x: contain; }
.spreadRail::-webkit-scrollbar { display: none; }
.spreadPanel { flex: 0 0 100%; width: 100%; height: 100%; overflow-y: auto; scroll-snap-align: start; scroll-snap-stop: always; outline: none; }
.editorialHome { display: grid; grid-template-columns: 1fr 1fr; grid-template-rows: 108px 1fr 152px; position: relative; background: linear-gradient(to right, #fff 50%, #000 50%); }
.editorialHeader { display: flex; align-items: center; justify-content: space-between; grid-column: 1 / -1; grid-row: 1; z-index: 1; padding: 0 0 0 4.2vw; }
.brandLogo { display: block; width: 58px; height: auto; flex-shrink: 0; }
.editorialLogo { display: inline-flex; align-items: center; font-size: 24px; letter-spacing: .08em; font-weight: 600; line-height: 1.3; color: #fff; }
.editorialHeader .editorialLogo { color: #09090a; }
.editorialLogo span { display: block; margin-top: 7px; font-size: 8px; letter-spacing: .15em; font-weight: 400; }
.contactTab { position: fixed; z-index: 1500; top: 0; right: 0; display: flex; align-items: center; justify-content: space-between; gap: clamp(12px, 2vw, 32px); width: var(--contact-tab-width); min-height: var(--contact-tab-height); padding: 24px clamp(18px, 2vw, 32px); border: 0; border-radius: 0; background: #e1b77b; color: #09090a; font-size: 13px; font-weight: 600; letter-spacing: .075em; text-transform: uppercase; transition: background .2s; }
.contactTab:hover { background: #edc990; color: #09090a; }
.contactTab > span:not(.longArrow) { flex-shrink: 0; white-space: nowrap; }
.contactTab .longArrow { flex: 1; min-width: 14px; width: auto; height: 24px; }
.contactTab:hover .longArrow { transform: translateX(8px); }
.editorialCopy { grid-column: 1; grid-row: 2; align-self: center; padding: 28px 6.4vw 32px 4.2vw; }
.editionLabel { font-size: 9px; letter-spacing: .17em; margin-bottom: 34px; color: #6c6a63; }
.editorialCopy h1 { font-family: var(--headline-font); font-size: clamp(88px, 9vw, 132px); line-height: .89; letter-spacing: -.025em; color: #09090a; font-weight: 400; }
.editorialCopy h1 em { font-weight: 400; color: #e1b77b; }
.editorialRole { margin-top: 23px; font-size: 16px; letter-spacing: .13em; text-transform: uppercase; color: #666; }
.editorialBio { display: flex; align-items: flex-start; gap: 26px; max-width: 450px; margin-top: 34px; position: relative; padding-top: 30px; }
.editorialBio > span { display: none; }
.editorialBio::before { content: ""; position: absolute; top: 0; left: 0; width: 48px; height: 4px; background: #e1b77b; }
.editorialBio p { font-size: 17px; line-height: 1.8; color: #626262; }
.editorialBio p + p { margin-top: 14px; }
.practiceNote { margin-top: 28px; font-size: 8px; letter-spacing: .12em; color: #76736b; }
.editorialPortrait { grid-column: 2; grid-row: 1 / -1; width: 100%; height: 100%; margin: 0; align-self: stretch; display: flex; min-height: 0; }
.portraitFrame { position: relative; flex: 1; min-height: 0; overflow: hidden; background: #000; }
.portraitFrame img { object-fit: cover; object-position: 50% 35%; filter: grayscale(1); }
.spreadNavigation { position: fixed; bottom: 0; left: 50%; transform: translateX(-50%); display: grid; grid-template-columns: 1fr 1fr; width: 40%; justify-self: center; align-self: end; z-index: 1500; }
.spreadNavigation button, .spreadNavigation > a { display: flex; flex-direction: row; align-items: center; justify-content: space-between; gap: 24px; min-height: 108px; border: 0; border-radius: 0; background: #e1b77b; color: #09090a; min-width: 0; padding: 24px 32px; font-family: Arial, Helvetica, sans-serif; font-size: 13px; font-weight: 600; letter-spacing: .075em; text-transform: uppercase; cursor: pointer; text-align: left; transition: background .2s; }
.spreadNavigation button > span:not(.longArrow), .spreadNavigation > a > span:not(.longArrow) { flex-shrink: 0; white-space: nowrap; }
.spreadNavigation .servicesDirection { border-left: 1px solid rgba(9,9,10,.2); }
.spreadNavigation button:hover, .spreadNavigation > a:hover { background: #edc990; }
.spreadNavigation .longArrow { flex: 1; min-width: 14px; width: auto; color: #09090a; }
.longArrow { display: block; width: 100%; height: 24px; overflow: visible; transition: transform .3s ease; }
.workDirection:hover .longArrow { transform: translateX(-8px); }
.servicesDirection:hover .longArrow { transform: translateX(8px); }
.destinationPanel { background: #09090a; padding: 0 max(24px, 5vw) 160px; color: #f5f3ed; }
.destinationPanel .innerPage { max-width: 1280px; margin: auto; }
.panelTop { min-height: 100px; display: flex; align-items: center; justify-content: space-between; font-size: 12px; }
.panelTop button, .panelReturn { border: 0; background: transparent; color: inherit; cursor: pointer; font: inherit; }
.panelTop button { display: flex; align-items: center; gap: 20px; }
.panelReturn { display: flex; align-items: center; gap: 36px; padding: 24px 0; font-size: 14px; }
.panelReturn svg { width: min(35vw, 400px); }
@media (min-width: 701px) and (max-height: 780px) {
  .editorialHome { grid-template-rows: 88px 1fr 120px; }
