  .editionLabel { margin-bottom: 22px; }
  .editorialCopy { padding-top: 20px; padding-bottom: 20px; }
  .editorialCopy h1 { font-size: clamp(64px, 7.6vw, 104px); }
  .editorialBio { margin-top: 22px; }
  .editorialRole { margin-top: 18px; }
