/* Navigation remains outside the scrolling sections and above every page. */
.persistentSite { padding-bottom: 140px; }
.persistentSite .header { padding-right: max(160px, 22vw); }
.sectionAnnouncement { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
