/* Alternating service images share the navigation's center line. */
.destinationPanel.servicesPanel { padding-inline: 0; }
.servicesPanel .panelTop { margin-inline: max(24px, 5vw); }
.servicesPanel .servicesPage { max-width: none; padding-inline: 0; }
.servicesPage > .pageHeading { padding-inline: max(24px, 5vw); max-width: 900px; }
.servicesPage .serviceRows {
  --service-image-height: clamp(600px, 42vw, 760px);
  --service-overlap: calc(var(--service-image-height) * .10);
  border: 0;
}
.servicesPage .serviceRow {
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  min-height: var(--service-image-height);
  gap: 0;
  padding: 0;
  border: 0;
  align-items: stretch;
}
.servicesPage .serviceRow + .serviceRow { margin-top: calc(-1 * var(--service-overlap)); }
.servicesPage .servicePhoto { grid-area: 1 / 1; height: auto; min-height: var(--service-image-height); border-radius: 0; }
.servicePhotoLayer { position: absolute; inset: -40px 0; }
.servicesPage .serviceCopy {
  grid-area: 1 / 2;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: flex-start;
  padding: var(--service-overlap) clamp(28px, 5vw, 96px);
}
.servicesPage .serviceRow:nth-child(even) .servicePhoto { grid-column: 2; }
.servicesPage .serviceRow:nth-child(even) .serviceCopy { grid-column: 1; }
@media (max-width: 700px) {
  .servicesPage .serviceRow { grid-template-columns: 1fr; min-height: 0; }
  .servicesPage .serviceRow + .serviceRow { margin-top: 0; }
  .servicesPage .serviceRow .servicePhoto { grid-area: 1 / 1; min-height: 0; height: auto; aspect-ratio: 1.18; }
  .servicesPage .serviceRow .serviceCopy { grid-area: 2 / 1; padding: 36px 24px 52px; }
}

/* Work starts beside its title, then alternates down the center seam. */
.workPage {
  --work-card-height: clamp(420px, 36vw, 560px);
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  align-items: start;
  padding-inline: 0;
}
.workPage > .pageHeading { grid-area: 1 / 1; padding: 0 48px 48px 0; }
.workPage .pageHeading h1 { font-size: clamp(56px, 6vw, 88px); }
