.workPage .workGallery { display: contents; }
.workPage .workCardReveal { height: var(--work-card-height); }
.workPage .workCardReveal:nth-child(even) { margin-top: calc(var(--work-card-height) * -.10); }
.workPage .workCardReveal:nth-child(odd):not(:first-child) { margin-top: calc(var(--work-card-height) * .18); }
.workPage .workPhoto { flex: 1; min-height: 260px; height: auto; }
.workPage .workLink { border-radius: 0; }
.workPage .workCaption { flex-shrink: 0; }
.workPage .caseStudyLink { flex-shrink: 0; }
@media (max-width: 700px) {
  .workPage { display: block; }
